<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';
$username=trim((string)($_GET['u']??''));$viewer=current_user($pdo);if($username===''){http_response_code(404);exit('Profile not found.');}
$q=$pdo->prepare("SELECT u.id,u.public_id,u.username,u.display_name,u.bio,u.website_url,u.profile_image_url,u.created_at,COALESCE(p.profile_visibility,'public') profile_visibility,COALESCE(p.search_visibility,1) search_visibility FROM users u LEFT JOIN user_preferences p ON p.user_id=u.id WHERE u.username=? AND u.status='active'");$q->execute([$username]);$p=$q->fetch();if(!$p||($p['profile_visibility']==='private'&&(!$viewer||$viewer['id']!=$p['id']))){http_response_code(404);exit('Profile not found.');}
$following=false;if($viewer&&$viewer['id']!=$p['id']){$q=$pdo->prepare('SELECT 1 FROM follows WHERE follower_user_id=? AND followed_user_id=?');$q->execute([$viewer['id'],$p['id']]);$following=(bool)$q->fetchColumn();}
$q=$pdo->prepare("SELECT COUNT(*) FROM annotations WHERE user_id=? AND visibility='public' AND status='published'");$q->execute([$p['id']]);$annotationCount=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(DISTINCT source_id) FROM annotations WHERE user_id=? AND visibility=\'public\' AND status=\'published\'');$q->execute([$p['id']]);$sourceCount=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM follows WHERE followed_user_id=?');$q->execute([$p['id']]);$followers=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM follows WHERE follower_user_id=?');$q->execute([$p['id']]);$followingCount=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT a.public_id,a.text_commentary,a.published_at,s.public_id source_public_id,s.title,c.selected_text,COALESCE(t.edited_text,t.raw_text) transcript_text FROM annotations a JOIN sources s ON s.id=a.source_id JOIN captures c ON c.id=a.capture_id LEFT JOIN annotation_transcripts t ON t.annotation_id=a.id WHERE a.user_id=? AND a.visibility='public' AND a.status='published' ORDER BY a.published_at DESC LIMIT 30");$q->execute([$p['id']]);$annotations=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($p['display_name'])?> · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a><nav><a href="/home.php">Home</a><a href="/explore.php">Explore</a><a href="/search.php">Search</a><?php if($viewer):?><a href="/saved.php">Saved</a><a href="/settings.php">Settings</a><?php else:?><a href="/login.php">Log in</a><?php endif?></nav></header><main class="panel article"><section class="profileHead"><div><div class="avatarLg"><?=h(mb_strtoupper(mb_substr($p['display_name'],0,1)))?></div></div><div><div class="meta">@<?=h($p['username'])?></div><h1><?=h($p['display_name'])?></h1><?php if($p['bio']):?><p class="commentary"><?=nl2br(h($p['bio']))?></p><?php endif?><?php if($p['website_url']):?><p><a href="<?=h($p['website_url'])?>" rel="nofollow noopener" target="_blank"><?=h($p['website_url'])?></a></p><?php endif?><div class="profileStats"><span><strong><?=$annotationCount?></strong> annotations</span><span><strong><?=$sourceCount?></strong> sources</span><span><strong><?=$followers?></strong> followers</span><span><strong><?=$followingCount?></strong> following</span></div><?php if($viewer&&$viewer['id']!=$p['id']):?><button id="follow" class="button secondary"><?=$following?'Following':'Follow'?></button><?php elseif($viewer&&$viewer['id']===$p['id']):?><a class="button secondary" href="/settings.php">Edit profile</a><?php endif?></div></section><hr><h2>Public annotations</h2><?php if(!$annotations):?><div class="card">No public annotations yet.</div><?php endif?><?php foreach($annotations as $a):?><article class="card"><div class="meta"><a href="/source.php?id=<?=h($a['source_public_id'])?>"><?=h($a['title']?:'Source')?></a> · <?=h($a['published_at'])?></div><?php if($a['text_commentary']):?><p><?=nl2br(h($a['text_commentary']))?></p><?php endif?><?php if($a['selected_text']):?><blockquote><?=h(mb_substr($a['selected_text'],0,700))?></blockquote><?php endif?><?php if($a['transcript_text']):?><details><summary>Audio transcript</summary><p><?=nl2br(h(mb_substr($a['transcript_text'],0,1200)))?></p></details><?php endif?><a href="/annotation.php?id=<?=h($a['public_id'])?>">Open annotation</a></article><?php endforeach?></main><?php if($viewer&&$viewer['id']!=$p['id']):?><script>const csrf=<?=json_encode(csrf_token())?>;document.querySelector('#follow')?.addEventListener('click',async e=>{const r=await fetch('/api/extension.php?action=follow',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({user_id:<?=json_encode($p['public_id'])?>})});const j=await r.json();if(j.ok)e.currentTarget.textContent=j.data.following?'Following':'Follow';});</script><?php endif?></body></html>
